INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Apple Bowl', 'Apple Bowl is a 1-player bowling game for the Apple II. Played from a 1st person perspective at a bowling alley, the player bowls in lane, while occasionally another member at the bowling alley will bowl in lanes. A throw indicator scrolls slowly along the bottom of the screen, and the player starts their bowl when the ball is in their preferred position. The player controls the power and spin of the ball using the game paddles, and the game attempts to accurately simulate the physics of bowling. Follows standard 10-pin bowling rules with a total of 10 frames of bowling.' FROM games WHERE igdb_id = 233315 ON CONFLICT (game_id, language_code) DO NOTHING;
