INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Showdown in 2100 A.D.', 'In an authentic acre of the old west, two gunslingers (human or android) duel for their lives. Each one has six bullets in his gun, and trees are placed all around. Each player has to hit his opponent ten times in order to win. At each hit, both players get their guns reloaded. They can also reload their guns anytime by taking the hidden bullets in the tree that matches their outfit' FROM games WHERE igdb_id = 23289 ON CONFLICT (game_id, language_code) DO NOTHING;
