INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ozma-wars', 40069, '1979-12-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/glye6fbcocaudepjoyse.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ozma Wars', 'Ozma Wars is a 1979 fixed shooter arcade game, and the very first game developed and published by SNK, who were still known as "Shin Nihon Kikaku" at the time. The game is also known as the second ever vertical shoot ''em up game, after Taito''s Space Invaders (which ran on the same arcade hardware), but is also additionally known as the first game with disparate "levels". The game is also notable for being the first action game to feature a supply of energy, resembling a life bar, a mechanic that has now become common in the majority of modern action games. The game allowed the player to refuel energy between each level, and it featured a large variety of alien enemies. The player controls a space craft which must fend off UFOs, meteors, and comets. Instead of lives, the player is given an energy reserve that is constantly diminishing; getting hit by the enemy causes gameplay to stop momentarily and a large amount of energy is depleted. Every so often, a mothership will appear and dock with the player''s spacecraft, allowing the energy to be refilled. There are 3-4 recognizable stages as the game progresses and new enemies begin to appear. After these, the mothership will appear, and the cycle starts over; this continues indefinitely until the energy reaches zero. There are two known bootleg versions of this game called Space Phantoms and Solar Flight. In Space Phantoms the player''s ship looks like an angel, and the enemies appear as different types of insects. Due to the game being monochrome and a conversion kit for Space Invaders, many Ozma Wars monitors still utilized the Space Invaders color overlay.' FROM games WHERE igdb_id = 40069 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 40069 AND ge.slug = 'shooter' ON CONFLICT DO NOTHING;
