INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('astro-fighter', 23049, '1979-10-01', 80, 'https://images.igdb.com/igdb/image/upload/t_cover_big/yzyllckn3ozsajmuafuk.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scmlto.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Astro Fighter', 'The game of Astro Fighter consists of 4 waves and a refueling stage, which are then repeated with increasingly higher difficulty. The player''s task is to eliminate the four successive waves of different types of attacking craft, while avoiding being hit by missiles and bombs, and then refuel by shooting the ''GS'' ship before repeating the process. The player starts with 3 lives and receives a bonus life on reaching a score of 5000. 300 bonus points are received for shooting each 6 falling bombs and for 950 for hitting the GS ship accurately on the first shot. A very large bonus of 10,000 is given for getting through 4 waves and refueling by using exactly 2 shots more than the minimum needed. As the higher levels of Astro Fighter are difficult to survive consistently, even for the best players, the highest scores have been achieved by the achieving the 10,000 bonus deliberately.' FROM games WHERE igdb_id = 23049 ON CONFLICT (game_id, language_code) DO NOTHING;
