INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Space Attack', 'Space Attack is an arcade shooting game, released by Sega for VIC Dual hardware in 1979. In the US it is thought to have been renamed Super Space Attack - whether there are in fact two separate games is currently unknown, but the two are extremely similar and "Super" is often dropped in internal Super Space Attack documents. It''s a Space Invaders clone and is almost identical to Taito''s classic. It is completely identical to another VIC Dual Space Invaders clone, Alpha Fighter, sharing full color graphics and a "bonus" round (in which the saucer briefly descends from the top of the screen after clearing the rest of usual set of invaders). Space Attack has a different set of graphics to Alpha Fighter, however. Similar to versions of Space Invaders, the upright cabinets for Space Attack use a mirror to project the image onto a textured surface (in this case, a starfield), giving the illusion that there is a background while playing.' FROM games WHERE igdb_id = 38573 ON CONFLICT (game_id, language_code) DO NOTHING;
