INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('space-fever', 39974, '1979-06-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2x38.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar7o7.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Space Fever', 'Shoot aliens as they move across the screen. Shoot the spaceship for extra points. Choose one of three games. Space Fever is a 1979 arcade game by Nintendo R&D2. Some sources claim that Ikegami Tsushinki also did design work on Space Fever. It was released in both monochrome and color versions. The gameplay is similar to Space Invaders, which had been released by Taito in 1978. It was distributed by Far East Video. The gameplay of Space Fever is reminiscent of Space Invaders (1978), where the player controls a laser cannon situated at the bottom of the screen and must defeat waves of enemy aliens. The aliens are arranged in rows and slowly move to the edge of the screen, before descending and continuing in the opposite direction. As more aliens are defeated, they increase in speed. A UFO will occasionally appear towards the top of the screen, which can be shot down for bonus points. There are three game modes that change the way the aliens move; the first presents two formations of enemies that move in opposite directions, the second continuously adds additional rows of aliens, and the third is functionally identical to Space Invaders.' FROM games WHERE igdb_id = 39974 ON CONFLICT (game_id, language_code) DO NOTHING;
