INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kadath', 'A Lovecraftian adventure inspired by the book "The Dream-Quest of Unknown Kadath". A text-only game with choose-your-own-adventure gameplay style. Made in 1979 by Gary Musgrave for the Altair 8800 and the Exidy Sorcery. In 1983 the Commodore PET got a "remake" of the game by the name "Eye of Kadath"' FROM games WHERE igdb_id = 386925 ON CONFLICT (game_id, language_code) DO NOTHING;
