INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bomb Bee', 'It is the sequel to Gee Bee, which was released in the previous year. The objective of the game is to use two paddles to bounce a ball which flies around and hit the colored bricks above it with the ball. When the bricks are cleared out of the side sections, it will turn that same side''s pop-bumper into 100 points instead of 10.' FROM games WHERE igdb_id = 38036 ON CONFLICT (game_id, language_code) DO NOTHING;
