INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('fire-one', 39515, '1979-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3udi.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scphjv.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fire One', 'Fire One! was a player-versus-player or player-versus-computer submarine showdown, designed and programmed by David Rolfe, Ted Michon, and Susan Ogg for Exidy in 1979. The cabinet was split into two halves, with each player controlling their first-person submarine perspective on their half of the screen. The primary objective of the game is to find and destroy the enemy''s submarine, while avoiding the enemy''s torpedoes. Through your virtual periscope you are free to launch one of your 8 torpedoes to take out any of the enemy''s various ships for extra points. It takes some time to reload each torpedo tube, so you must be judicious in how you plan your attacks. In addition to being able to control the left/right rotation of your periscope, the game also features a submerge button which you can use to temporarily hide from the enemy. Holding this button down keeps you hidden but also keeps you out of the action, allowing the enemy free reign over the seas.' FROM games WHERE igdb_id = 39515 ON CONFLICT (game_id, language_code) DO NOTHING;
