INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Memory I', 'This cartridge contains 16 game variations for one or two players. Each program calls for concentration and retentive powers. In the first group of programs, a paper chase is held across the screen: players have to locate a concealed flag and are given frequent hints in the course of their search. In the second group, various symbols are concealed on the screen in pairs, and these too have to be located in the memory card game.' FROM games WHERE igdb_id = 68610 ON CONFLICT (game_id, language_code) DO NOTHING;
