INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('lunar-rescue', 40007, '1979-11-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/v1zwo8vbzikc6kwdmply.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc6d7m.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lunar Rescue', 'The game starts with the player''s spacecraft docked inside the mothership at the top of the screen. Below the mothership is an asteroid field and below that, the surface of the moon. There are three platforms which can be landed on and six stranded astronauts that need rescuing. You control a small spacecraft. The player must press the button to release their spacecraft from the mothership and manoeuvre through the asteroid field. The craft can only move left or right or use up a finite amount of fuel by engaging the thrust (the same button again) to slow its descent. If the craft is landed successfully on one of the available platforms, one of the astronauts will run towards and board the craft. The asteroid belt now changes into a swarm of flying saucers, some of which drop bombs. The player must now guide the spacecraft back up to the mothership (the craft ascends without using up fuel), avoiding the flying saucers. The thrust button is now a fire button which can be used to shoot at enemies above (as in Space Invaders). Finally, the craft must be docked with the mothership using the bay opening. If the side of the mothership or any part of the ship outside of the opening is hit, the rescued astronaut falls to the surface and dies. If the mothership is missed altogether, the craft explodes. After all six people have been rescued (or killed providing the player still has lives remaining), the game starts again at a higher level.' FROM games WHERE igdb_id = 40007 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 40007 AND ge.slug = 'arcade' ON CONFLICT DO NOTHING;
