INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('starhawk--1', 23202, '1979-03-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4v8o.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scphxt.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Starhawk', 'Starhawk is a 1979 vector arcade game by Cinematronics. Starhawk is a shoot ''em up with a fixed environment. The game was unique at the time as it presented the graphics in a pseudo-three dimensional way. Essentially, the game is a simple video game version of the Star Wars: Episode IV trench run. The game was later ported to the Vectrex video game console in 1982. The game is remembered as having quite advanced graphics for the time and being the first video game based upon or to have noticeable references to Star Wars.' FROM games WHERE igdb_id = 23202 ON CONFLICT (game_id, language_code) DO NOTHING;
