INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Las Vegas Poker & Blackjack', 'Las Vegas Poker & Blackjack is a computerized version of different types of Poker and Blackjack, including 7-Card Stud and 5-Card Draw. The player inputs how much "money" that is available to bet with. There is one and two-player games, and Las Vegas Poker & Blackjack includes a dealer to play against. Developed by John Brooks for APh Technological Consulting and published by Mattel Electronics' FROM games WHERE igdb_id = 71274 ON CONFLICT (game_id, language_code) DO NOTHING;
