INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('space-guerilla', 392974, '1979-10-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobof9.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar5hav.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Space Guerilla', 'Space Guerrilla is a fixed-screen shooter in the vein of Space Invaders but with some interesting twists. The player controls their tank at the bottom of the screen and must prevent an alien invasion. Instead of the typical four bunkers, there are three pieces of scenery with buildings. The attract screen starts with a little animation of aliens landing on one of them and peeing. Another difference with the typical Space Invaders clone is that while the ships fly in a block formation, they don''t go back and forth between the screen boundaries. Instead they fly past and go out of view again, before flying back. Some ships also dive down towards the bottom of the screen like in Galaxian. When the player loses all their lives the game is lost.' FROM games WHERE igdb_id = 392974 ON CONFLICT (game_id, language_code) DO NOTHING;
