INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Avatar', 'Avatar is an early graphics-based multi-user highly interactive role-playing computer game, created on the University of Illinois'' Control Data Corporation PLATO system in the late 1970s. It has graphics for navigating through a dungeon and chat-style text for player status and communication with others. It can currently be played online via Cyber1 or a simulation called Javatar. What makes Avatar popular is the high level of interactivity with other players and the sense of community that develops. Development on Avatar began on the University of Illinois PLATO system around 1977; the first version was released by Bruce Maggs, Andrew Shapira, and David Sides in 1979.' FROM games WHERE igdb_id = 80928 ON CONFLICT (game_id, language_code) DO NOTHING;
