INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Warrior', 'Warrior is a 1979 arcade fighting game and is considered one of the first games of its genre. Developed by Tim Skelly while working at Cinematronics, it was released under the Vectorbeam company name shortly before Cinematronics closed Vectorbeam down. The game featured two dueling knights rendered in monochrome vector graphics and based on crude motion capture techniques. Due to the limitations of the hardware used, the processor could not render the characters and gaming environment at the same time and backgrounds were printed, with the characters projected on the top.' FROM games WHERE igdb_id = 16974 ON CONFLICT (game_id, language_code) DO NOTHING;
