INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Galaxy Wars', 'The aim of this arcade game is to launch missiles from the bottom of the screen at enemy spacecraft located at the top. To get there, the missile must pass through a asteroid belt flying across the screen and avoid the shots being fired down from the spacecraft. It is the players job to control the missile. Once launched it can be moved left and right and can be sped up by using the boost to speed it''s way out of trouble. Points scored depend on the location of the hit on the enemy spacecraft. The speed at which enemy spacecraft move increases as the number of them decreases. Once all spacecraft have been destroyed, another wave starts, the speed decreases again and the process repeats. A life is lost when a missile is hit by a shot or collides with an asteroid.' FROM games WHERE igdb_id = 39990 ON CONFLICT (game_id, language_code) DO NOTHING;
