INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Down the Trench', 'The player controls a small vessel, which must travel through a trench while avoiding laser fire, similar to the scene from Star Wars. The player''s ship can move in all directions, and the difficulty determines how often lasers fire. After getting close to the end of the trench, the game transitions to targeting mode, where the player must align a targeting box to destroy the Death Star.' FROM games WHERE igdb_id = 169269 ON CONFLICT (game_id, language_code) DO NOTHING;
