INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Space Chaser', 'Collect all the dots in the maze without colliding with (or being collided by) the missile. You can use your speed boost as long as you have fuel left. If the missile gets behind you on a long stretch it will speed up and the only way to avoid collision then is to turn a corner.' FROM games WHERE igdb_id = 39803 ON CONFLICT (game_id, language_code) DO NOTHING;
