INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Out of This World! / Helicopter Rescue!', 'Two titles are available in this cart: - Out of This World! is a slightly upgraded version of Space Rendezvous. It is somewhat similar to Lunar Lander. - Helicopter Rescue! has the player in control of the Daredevil helicopter rescue ship. The object is to rescue the most people from the Doomsday Hotel''s rooftop within two minutes and place them in the Rescue Station.' FROM games WHERE igdb_id = 165255 ON CONFLICT (game_id, language_code) DO NOTHING;
