INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bally Pin', 'Bally Pin was considered the best pinball simulation ever offered for any home gaming system at the time. The game is played with two joysticks by up to four players. Each player is given 5 balls. Players earn points by using the flippers to hit the bumpers, drop targets, upper kicker targets, and spinner' FROM games WHERE igdb_id = 130870 ON CONFLICT (game_id, language_code) DO NOTHING;
