INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('barrier', 38546, '1979-08-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3utv.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scmto4.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Barrier', 'Barrier is a maze arcade game using vector graphics released by Vectorbeam in 1979. In this very basic game, players move a small triangle around on the grid, while attempting to avoid the diamonds that are also moving around on the grid. Reaching the end of the grid teleports the player back to the front of the grid to gain points. The game is played on a 3x9 grid that is displayed at angle to make it appear to be in 3-D. The game was sold to Vectorbeam by Cinematronics.' FROM games WHERE igdb_id = 38546 ON CONFLICT (game_id, language_code) DO NOTHING;
