INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yakyuuken', 'One of the very first erotic video games ever released. Gameplay is comprised of a strip variation of rock-paper-scissors, based on a concept popularized by "Konto 55-gou no urabangumi wo buttobase!", a variety show which ran from April 27, 1969 to March 29, 1970. Players set how many articles of clothing they would like their opponent Megumi to wear, and after each victory she removes one piece until she is nude. Originally released for Sharp MZ-80K systems on cassette and sold at Personal-computer Shop Kouchi, it was later ported to Sharp MZ-700 in a bundle with Breakout clone ''Rowdy-Ball'', and as a type-in program published in ''MZ-700 Joyful Pack.''' FROM games WHERE igdb_id = 248812 ON CONFLICT (game_id, language_code) DO NOTHING;
