INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ameprod Television Game 10', 'The Ameprod Television Game 10 is a dedicated first-generation home video game console that was produced in Poland by Elwro from 1978 to 1981, then the production was transferred to PPZ Ameprod. The TVG-10, thanks to the AY-3-8500 chip, featured six integrated games (Pong, Soccer, Squash, Practice and 2 shooting games), of which without the separately available lightgun called Videotraf only four games were playable.' FROM games WHERE igdb_id = 243416 ON CONFLICT (game_id, language_code) DO NOTHING;
