INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Laser War', 'The players are in the Battle Control Central at the heart of the United Planets Interstellar Galactic Empire. From there, they monitor the activity of the twin solar systems of Terien and Lorien, forty-three billion light years away. Their mission is to control to protect the planets of those solar systems from the invasion fleet with the remote controlled battle cruisers. They''ll control their ships with the joystick and fire lasers with the action button. The invasion fleet will shoot the players and the planets as well. Shot planets will have their colors changed and will be conquered when their colors match the invaders ship''s colors. If the players'' ship is destroyed, a new one will be launched from one of the planets with their color. If there''s no planet with their color, they''ll have to wait until a planet''s color change to theirs. If the players crash into planets with a color different than theirs, both the ship and the planet will be destroyed. Destroyed planets won''t come back, but the central planet at each orbit is indestructible. Players can also hide their ships in their own planets, by landing on them. Planets with ships landed will blink. The winner is the player who first destroys ten enemy ships.' FROM games WHERE igdb_id = 41567 ON CONFLICT (game_id, language_code) DO NOTHING;
