INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('star-fire', 23160, '1979-06-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/myseuevgbpm2bf0nxvjn.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scplo8.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Fire', 'Star Fire is an early color game programmed by David Rolfe with graphics designed by Ted Michon and Susan Ogg. It was released by Exidy in 1979. Star Fire is a first-person space shooter where your mission is to seek out and destroy enemy spacecraft while avoiding incoming missiles. If a number of elements of Star Fire seem similar to Star Wars, your eyes are not deceiving you. Star Fire was originally designed as a Star Wars game, with the eventual hope that either a license would be purchased or that they would change enough of the elements to avoid any legal entanglements. Originally, the authors had hoped that Midway would pick up the game for distribution, but they passed and instead Exidy purchased the game and released it. Star Fire was the first game to come in an environmental cabinet, designed by Michael Cooper-Hart. Even more importantly from a historical perspective, Star Fire was the first game to keep a high score list where the player could enter his or her initials. Prior games had tracked the concept of a high score, but Star Fire was the first to let you personalize the high score entry and display a top ten list with your initials next to your high score. An update to Star Fire, simply called "Star Fire II", was intended to go into the last run of Star Fire units. It features a more refined high score display and easier high score input.' FROM games WHERE igdb_id = 23160 ON CONFLICT (game_id, language_code) DO NOTHING;
