INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Trek: Phaser Strike', 'Star Trek: Phaser Strike is a shoot ''em up video game that was published by Milton Bradley in 1979, and released for the Microvision at the same time as the film Star Trek: The Motion Picture. In the game, the player must destroy ships with phaser banks located at the bottom of the screen. The Star Trek name was later dropped and the game was sold as Phaser Strike. It was sold under other names internationally: Shooting Star in Germany, Italy and UK, and Cannon Phaser in France and Canada.' FROM games WHERE igdb_id = 68129 ON CONFLICT (game_id, language_code) DO NOTHING;
