INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Number Magic', 'Number Magic is an educational game designed to teach young children arithmetic. It is based around a stage magic theme, and includes many images of rabbits and top hats.  Three modes are available. Quick Quiz displays randomly-generated arithmetic questions and the player is scored by correct answers. Comp Quiz allows the user to customize several quiz options, such as enable time limits, choose whether to complete answers or missing numbers, and select custom or randomly-generated questions. Electroflash is similar to Comp Quiz but all of the questions include a specific number and arithmetic operation, chosen by the user.  After each quiz, the player can choose to repeat the same quiz, generate a new quiz with the same options, select a new quiz type, or quit.' FROM games WHERE igdb_id = 42183 ON CONFLICT (game_id, language_code) DO NOTHING;
