INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Basic Programming', 'Basic Programming attempted to teach simple computer programming on the Atari 2600. It was released in 1979, and it was one of only a few non-gaming cartridges ever designed for the 2600. The programming language was superficially similar to dialects of BASIC, but differed in many important aspects. The extremely small RAM size of the Atari 2600, 128 bytes, severely restricted the possibilities of this cartridge for writing programs.' FROM games WHERE igdb_id = 54794 ON CONFLICT (game_id, language_code) DO NOTHING;
