INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Monaco GP', 'Monaco GP is an arcade game that was released by Sega in 1979. The game was released in three cabinet styles, a vertical upright cabinet, a cocktail table and sit-down ''deluxe'' cabinet. A sequel, Pro Monaco GP, was released in 1980, and was later followed by Super Monaco GP and Ayrton Senna''s Super Monaco GP II. Monaco GP was ported to the SG-1000 in 1983.' FROM games WHERE igdb_id = 6118 ON CONFLICT (game_id, language_code) DO NOTHING;
