INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'War of Nerves!', 'This is some sort of a capture the flag game. Instead of a flag, the object is to capture the enemy general.  Two armies share the screen, the Army of Northwestonia in the upper left corner and the Army of Southeasternia in the lower right corner. The players control the general of the army with the joystick. The robots in each army are controlled by the computer, and their mission is to capture the enemy general.' FROM games WHERE igdb_id = 18826 ON CONFLICT (game_id, language_code) DO NOTHING;
