INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Speed Freak', 'Speed Freak is a monochrome vector arcade game created by Vectorbeam in 1979. It is a behind-the-wheel driving simulation where the driver speeds down the computer generated road past other cars, hitchikers, trees, cows and cacti. Occasionally a plane will fly overhead towards the screen. One must avoid crashing into these objects and complete the race in the alloted time. The player can crash as many times as he wants before the time runs out and players were treated to two different crash animations. The first was a simple cracked windshield effect, the second was a crash where the car explodes into car parts that fly through the air.' FROM games WHERE igdb_id = 46764 ON CONFLICT (game_id, language_code) DO NOTHING;
