INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Field Goal', 'A football/Breakout-style arcade game made by Taito. Despite its name it is less of a football game and more of a Breakout variant, with the player represented by a paddle and the opposing team guarding the goal and at the top of the screen. The game is controlled with a paddle, like most Breakout variants.' FROM games WHERE igdb_id = 172656 ON CONFLICT (game_id, language_code) DO NOTHING;
