INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('marksman-slash-depth-charge', 27220, '1979-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1wz5.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc7k2t.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Marksman / Depth charge', 'Two titles are available in this cart: Depth Charge is a single-player BattleShip variant. The player controls a cannon in a top-down view trying to destroy 7 submarines hidden in the area of water shown on screen. The area is a 8x8 grid, and the player controls a white cross-hair over it with the joystick. Pressing the action button will shoot the cannon. If a submarine is hidden in that particular area, a blue square will appear, marking it. If there are no submarines, the game will warn the player with a sound and that area will continue unmarked. There are submarines of 4 different sizes, with there being 3 with one section each, 2 with 2 sections each, 1 with 3 sections and 1 with 4 sections. The game keeps track of the number of shots tried by the player, and the total is shown at the end of the game, when all submarines are destroyed. Marksman is a shooting gallery game. The player can choose between 2 game durations: 1 minute or 3 minutes. The game is played in a first person perspective, with the player seeing the rifle and the targets in front of it. A line of targets will scroll from right to left, bouncing up and down in front of the rifle and the player has to aim at them and shoot. There are 9 different targets which grant the player scores from 1 to 9 points each. When the player reaches 100 points, the targets start to move faster. The game ends when the time reaches 0:00 or when the player runs out of shots (starting with 24).' FROM games WHERE igdb_id = 27220 ON CONFLICT (game_id, language_code) DO NOTHING;
