INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Monkey Magic', 'Monkey Magic is a video game released in arcades by Nintendo in 1979. It is a Breakout clone and one of Nintendo''s earliest arcade games. Some sources claim that Ikegami Tsushinki also did design work on Monkey Magic. Players control a paddle to hit the ball at a large number of blocks shaping a monkey''s face. Players can also earn different numbers of points by catching blocks that fall, as well as hitting the ball in different places.' FROM games WHERE igdb_id = 145394 ON CONFLICT (game_id, language_code) DO NOTHING;
