INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bowling', 'The game is based on the game of bowling, playable by one player or two players alternating. In all six variations, games last for 10 frames, or turns. At the start of each frame, the current player is given two chances to roll a bowling ball down an alley in an attempt to knock down as many of the ten bowling pins as possible. The bowler (on the left side of the screen) may move up and down his end of the alley to aim before releasing the ball. In four of the game''s six variations, the ball can be steered before it hits the pins. Knocking down every pin on the first shot is a strike, while knocking every pin down in both shots is a spare. The player''s score is determined by the number of pins knocked down in all 10 frames, as well as the number of strikes and spares acquired.' FROM games WHERE igdb_id = 18005 ON CONFLICT (game_id, language_code) DO NOTHING;
