INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('3-d-tic-tac-toe', 11854, '1979-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8wf6.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/wwirei4t3m4e4hi1q0re.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '3-D Tic-Tac-Toe', 'The game is similar to the traditional game of tic-tac-toe, but is played on four 4×4 grids stacked vertically; it is basically a computerized version of the board game Qubic using traditional tic-tac-toe notation and layout. To win, a player must place four of their symbols on four squares that line up vertically, horizontally, or diagonally, on a single grid, or spaced evenly over all four grids. This creates a total of 76 possible ways to win, in comparison to eight possible ways to win on a standard 3×3 board. The game has nine variations: it can be played by two players against each other, or one player can play against a built-in AI on one of eight different difficulty settings. The game uses the standard joystick controller.' FROM games WHERE igdb_id = 11854 ON CONFLICT (game_id, language_code) DO NOTHING;
